using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if not available
//    Use a resolver that only knows about Person, not about Order.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Only allow Person metadata through
            if (ti.Type != typeof(Person))
                throw new NotSupportedException();
        })
};
// Force the resolver to cache Person so options are "ready"
_ = limited.GetTypeInfo(typeof(Person));

bool foundPerson = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pInfo);
bool foundOrder  = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? oInfo);

Console.WriteLine($"TryGet Person: {foundPerson} (info is null: {pInfo is null})");
Console.WriteLine($"TryGet Order:  {foundOrder}  (info is null: {oInfo is null})");

